class TripleStoreFrontierMutationJournalLifecycleTest {

	private static final int JOURNAL_CAPACITY = 16_384;

	@Test
	void offModeWritesOnlyDurableGapMetadata(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.OFF);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			for (int index = 0; index < 3; index++) {
				assertTrue(store.storeTriple(101L + index, 201L, 301L + index, 0L, true));
			}
			store.commit();

			assertEquals(List.of(), store.readFrontierMutationsAfter(0L, 100),
					"OFF mode must not retain per-statement raw journal rows");
			JournalState state = journalState(store);
			assertEquals(1L, state.latestSequence(), "one OFF transaction needs one durable invalidation coordinate");
			assertEquals(1L, state.gapThroughSequence());
			assertEquals(0L, state.retainedMutationCount());
		}
	}

	@Test
	void reopeningEnabledAfterOffWritesExposesPersistedGap(@TempDir Path directory) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(FrontierEstimatorMode.OFF), null)) {
			store.startTransaction();
			assertTrue(store.storeTriple(101L, 201L, 301L, 0L, true));
			store.commit();
		}

		try (TripleStore reopened = new TripleStore(directory.toFile(),
				config(FrontierEstimatorMode.AUTHORITATIVE), null)) {
			JournalState state = journalState(reopened);
			assertEquals(1L, state.latestSequence());
			assertEquals(1L, state.gapThroughSequence(),
					"re-enabling Frontier must force a base rebuild instead of trusting a stale sidecar");
			assertThrows(Exception.class, () -> reopened.readFrontierMutationsAfter(0L, 100));
		}
	}

	@Test
	void capacityOverflowRetainsBoundedTailAndMarksMissingPrefix(@TempDir Path directory) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(),
				config(FrontierEstimatorMode.AUTHORITATIVE), null)) {
			store.startTransaction();
			for (int index = 0; index <= JOURNAL_CAPACITY; index++) {
				assertTrue(store.storeTriple(index + 1L, 1L, index + 100_000L, 0L, true));
			}
			store.commit();

			JournalState state = journalState(store);
			assertEquals(JOURNAL_CAPACITY + 1L, state.latestSequence());
			assertEquals(1L, state.gapThroughSequence());
			assertEquals(JOURNAL_CAPACITY, state.retainedMutationCount());
			List<FrontierMutation> retained = store.readFrontierMutationsAfter(1L, JOURNAL_CAPACITY);
			assertEquals(JOURNAL_CAPACITY, retained.size());
			assertEquals(2L, retained.getFirst().sequence());
			assertEquals(JOURNAL_CAPACITY + 1L, retained.getLast().sequence());
		}
	}

	@Test
	void legacyJournalPartiallyAcknowledgedAboveCapacityMigratesToValidBoundedV1(@TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE);
		long legacyLatest = JOURNAL_CAPACITY + 2L;
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			writeLegacyJournal(store, legacyLatest);
			resetReadersAfterFixtureWrite(store);
			acknowledge(store, 1L);

			JournalState state = journalState(store);
			assertEquals(legacyLatest, state.latestSequence());
			assertEquals(1L, state.acknowledgedThroughSequence());
			assertEquals(2L, state.gapThroughSequence());
			assertEquals(JOURNAL_CAPACITY, state.retainedMutationCount());
			assertThrows(IOException.class, () -> store.readFrontierMutationsAfter(1L, JOURNAL_CAPACITY));
			List<FrontierMutation> retained = store.readFrontierMutationsAfter(2L, JOURNAL_CAPACITY);
			assertEquals(JOURNAL_CAPACITY, retained.size());
			assertEquals(3L, retained.getFirst().sequence());
			assertEquals(legacyLatest, retained.getLast().sequence());
		}

		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			reopened.startTransaction();
			assertTrue(reopened.storeTriple(90_001L, 90_002L, 90_003L, 0L, true));
			reopened.commit();

			JournalState state = journalState(reopened);
			assertEquals(legacyLatest + 1L, state.latestSequence());
			assertEquals(3L, state.gapThroughSequence());
			assertEquals(JOURNAL_CAPACITY, state.retainedMutationCount());
		}
	}

	@Test
	void failedPublicationLeavesUnacknowledgedRowsRestartReplayable(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			assertTrue(store.storeTriple(101L, 201L, 301L, 0L, true));
			assertTrue(store.storeTriple(102L, 201L, 302L, 0L, true));
			store.commit();
			assertEquals(2L, journalState(store).retainedMutationCount());
		}

		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			JournalState state = journalState(reopened);
			assertEquals(0L, state.gapThroughSequence());
			assertEquals(2L, state.retainedMutationCount(),
					"publication failure must not acknowledge or discard replayable rows");
			assertEquals(2, reopened.readFrontierMutationsAfter(0L, 100).size());
		}
	}

	@Test
	void successfulPublicationAcknowledgementPrunesOnlyCoveredRows(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			assertTrue(store.storeTriple(101L, 201L, 301L, 0L, true));
			assertTrue(store.storeTriple(102L, 201L, 302L, 0L, true));
			store.commit();
			store.startTransaction();
			assertTrue(store.storeTriple(103L, 201L, 303L, 0L, true));
			assertTrue(store.storeTriple(104L, 201L, 304L, 0L, true));
			store.commit();

			acknowledge(store, 2L);
			JournalState state = journalState(store);
			assertEquals(4L, state.latestSequence());
			assertEquals(0L, state.gapThroughSequence());
			assertEquals(2L, state.retainedMutationCount());
			List<FrontierMutation> retained = store.readFrontierMutationsAfter(2L, 100);
			assertEquals(List.of(3L, 4L), retained.stream().map(FrontierMutation::sequence).toList());
			assertThrows(IllegalArgumentException.class, () -> acknowledge(store, 5L));
		}
	}

	private static LmdbStoreConfig config(FrontierEstimatorMode mode) {
		return new LmdbStoreConfig("spoc,posc").setFrontierEstimatorMode(mode);
	}

	private static void writeLegacyJournal(TripleStore store, long latestSequence) throws Exception {
		Field dbiField = TripleStore.class.getDeclaredField("frontierMutationJournalDbi");
		dbiField.setAccessible(true);
		int dbi = dbiField.getInt(store);
		LmdbUtil.transaction(store.env, (stack, txn) -> {
			LmdbUtil.E(mdb_drop(txn, dbi, false));
			MDBVal key = MDBVal.malloc(stack);
			MDBVal value = MDBVal.malloc(stack);
			ByteBuffer keyBytes = stack.malloc(Long.BYTES).order(ByteOrder.BIG_ENDIAN);
			ByteBuffer legacyMetadata = stack.malloc(Long.BYTES).order(ByteOrder.BIG_ENDIAN);
			keyBytes.putLong(0L).flip();
			legacyMetadata.putLong(latestSequence).flip();
			key.mv_data(keyBytes);
			value.mv_data(legacyMetadata);
			LmdbUtil.E(mdb_put(txn, dbi, key, value, MDB_NOOVERWRITE));

			ByteBuffer row = stack.malloc(Integer.BYTES * 2 + Long.BYTES * 5).order(ByteOrder.BIG_ENDIAN);
			for (long sequence = 1L; sequence <= latestSequence; sequence++) {
				keyBytes.clear();
				keyBytes.putLong(sequence).flip();
				row.clear();
				row.putInt(1);
				row.putInt(3);
				row.putLong(sequence);
				row.putLong(100_000L + sequence);
				row.putLong(1L);
				row.putLong(200_000L + sequence);
				row.putLong(0L);
				row.flip();
				key.mv_data(keyBytes);
				value.mv_data(row);
				LmdbUtil.E(mdb_put(txn, dbi, key, value, MDB_NOOVERWRITE));
			}
			return null;
		});
	}

	private static void resetReadersAfterFixtureWrite(TripleStore store) throws Exception {
		Method method = TripleStore.class.getDeclaredMethod("resetReadersAfterIndependentWrite");
		method.setAccessible(true);
		method.invoke(store);
	}

	private static JournalState journalState(TripleStore store) throws Exception {
		Method method;
		try {
			method = TripleStore.class.getDeclaredMethod("frontierMutationJournalState");
		} catch (NoSuchMethodException e) {
			throw new AssertionError("TripleStore must expose its persisted journal lifecycle state", e);
		}
		method.setAccessible(true);
		Object state = method.invoke(store);
		Class<?> stateType = state.getClass();
		return new JournalState(
				(long) stateType.getDeclaredMethod("latestSequence").invoke(state),
				(long) stateType.getDeclaredMethod("gapThroughSequence").invoke(state),
				(long) stateType.getDeclaredMethod("acknowledgedThroughSequence").invoke(state),
				(long) stateType.getDeclaredMethod("retainedMutationCount").invoke(state));
	}

	private static void acknowledge(TripleStore store, long coveredSequence) throws Exception {
		Method method;
		try {
			method = TripleStore.class.getDeclaredMethod("acknowledgeFrontierMutationsThrough", long.class);
		} catch (NoSuchMethodException e) {
			throw new AssertionError("TripleStore must prune only explicitly acknowledged Frontier coverage", e);
		}
		method.setAccessible(true);
		try {
			method.invoke(store, coveredSequence);
		} catch (InvocationTargetException e) {
			if (e.getCause()instanceof Exception exception) {
				throw exception;
			}
			throw e;
		}
	}

	private record JournalState(long latestSequence, long gapThroughSequence, long acknowledgedThroughSequence,
			long retainedMutationCount) {
	}
}
